{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Imatinib, which shares an arylaminopyrimidine/piperazine-like scaffold with the query, has a measured absolute oral bioavailability of 98% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "GSK1322322, a piperazine-containing oral drug with moderate similarity, showed 77% absolute oral bioavailability in healthy volunteers after a meal, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Abemaciclib, a piperazine-containing oral kinase inhibitor structurally related to the query, has a consistent absolute oral bioavailability of 45% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Brepocitinib, a heteroaromatic oral drug, had an estimated absolute bioavailability of 75% in a human mass balance study, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Risdiplam, a heteroaromatic oral drug with high oral bioavailability due to near-complete absorption and negligible first-pass extraction, supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Tacrolimus, the highest-similarity analogue, has oral bioavailability of approximately 20–25%, which is at the threshold but still supports F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "TFMPP, a small phenylpiperazine, showed low oral bioavailability in humans (<1% urinary recovery), providing a contradictory low-F example, but its much smaller and simpler structure limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted to have high oral bioavailability (F ≥ 20%). Most transferable experimental evidence from piperazine/heteroaromatic oral drugs (imatinib 98%, GSK1322322 57–77%, abemaciclib 45%, brepocitinib 75%, risdiplam high) supports high F. The highest-similarity analogue tacrolimus is borderline (~20–25%) but still meets the threshold. The only low-F example (TFMPP) is structurally distant and outweighed.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule.",
    "The highest-similarity analogue (tacrolimus) is structurally dissimilar despite its Morgan score and is only borderline at the 20% threshold.",
    "Most analogues have low-to-moderate Morgan similarity (0.21–0.42), so quantitative F transfer is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

